using FluentValidation;namespace Namaa.Application.PaymentVouchers.Commands.CreatePaymentVoucher;public sealed class CreatePaymentVoucherCommandValidator:AbstractValidator<CreatePaymentVoucherCommand>{public CreatePaymentVoucherCommandValidator(){RuleFor(x=>x.VoucherNumber).NotEmpty().MaximumLength(30);RuleFor(x=>x.PaymentMethod).Must(x=>x is "Cash" or "BankTransfer" or "Card" or "Cheque" or "Other");RuleFor(x=>x.Amount).GreaterThan(0);RuleFor(x=>x).Must(x=>x.SupplierId.HasValue||!string.IsNullOrWhiteSpace(x.BeneficiaryName)).WithMessage("Supplier or beneficiary is required.");}}
